// Tidy the input and run the basic data checks (ID, type, channel, empty body).
const cfg = $('2. Load Config').first().json.config;
const validTypes = Object.keys(cfg.type_rules);
const seen = {};
const out = [];
let n = 0;

const str = function (v) { return (v === null || v === undefined) ? '' : String(v); };

for (const item of $input.all()) {
  n += 1;
  const r = (item.json && typeof item.json === 'object') ? item.json : {};
  const j = {
    row_number: n,
    template_id: str(r.template_id).trim(),
    name: str(r.name).trim() || '(unnamed)',
    type: str(r.type).trim().toLowerCase(),
    channel: str(r.channel).trim().toLowerCase(),
    subject: str(r.subject),
    body: str(r.body),
    last_edited_by: str(r.last_edited_by).trim() || 'unknown',
    issues: []
  };
  const add = function (code, severity, category, message, evidence, fix) {
    j.issues.push({ code: code, severity: severity, category: category, owner: cfg.owners[category],
      message: message, evidence: evidence || '', fix: fix || '', auto_fixable: false });
  };

  if (!j.template_id) {
    j.template_id = 'AUTO-' + String(n).padStart(3, '0');
    add('ID_MISSING', 'medium', 'data', 'Template has no ID, so a temporary one was assigned.', j.template_id, 'Give every template a unique ID such as T-027.');
  } else {
    const key = j.template_id.toUpperCase();
    if (seen[key]) {
      add('DUP_ID', 'high', 'data', 'This template ID is used more than once.', j.template_id + ' (first seen at row ' + seen[key] + ')', 'Give each template its own ID, or delete the duplicate.');
    } else {
      seen[key] = n;
    }
  }

  if (validTypes.indexOf(j.type) === -1) {
    add('TYPE_UNKNOWN', 'high', 'config', 'Template type is not on the approved list, so type-specific rules could not be applied.',
      j.type || '(blank)', 'Use one of: ' + validTypes.join(', ') + '.');
  }
  if (cfg.channels.indexOf(j.channel) === -1) {
    add('CHANNEL_UNKNOWN', 'high', 'config', 'Channel is missing or not recognised, so delivery checks (length, subject line) were skipped.',
      j.channel || '(blank)', 'Set the channel to sms or email.');
  }
  if (j.body.trim() === '') {
    add('BODY_EMPTY', 'critical', 'content', 'Template body is empty.', '', 'Write the message text before this template is used.');
  }
  out.push({ json: j });
}
return out;

// UK English and wording checks: US spelling, US dates, dollar amounts, wordy phrases.
const cfg = $('2. Load Config').first().json.config;
const escRe = function (s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); };

const spellKeys = Object.keys(cfg.uk_spelling).sort(function (a, b) { return b.length - a.length; });
const spellRe = new RegExp('\\b(' + spellKeys.map(escRe).join('|') + ')\\b', 'gi');
const plainKeys = Object.keys(cfg.plain_english).sort(function (a, b) { return b.length - a.length; });
const plainRe = new RegExp('\\b(' + plainKeys.map(escRe).join('|') + ')\\b', 'gi');
const usDateRe = /\b(?:0?[1-9]|1[0-2])\/(?:1[3-9]|2[0-9]|3[01])\/(?:\d{4}|\d{2})\b/g;
const dollarRe = /\$\s?\d[\d,.]*/g;

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const add = function (code, severity, category, message, evidence, fix, auto) {
    j.issues.push({ code: code, severity: severity, category: category, owner: cfg.owners[category],
      message: message, evidence: evidence || '', fix: fix || '', auto_fixable: !!auto });
  };
  const scan = (j.subject + '\n' + j.body).replace(/\{\{[^}]*\}\}/g, ' ').replace(/https?:\/\/\S+/g, ' ');

  const us = {};
  let m;
  spellRe.lastIndex = 0;
  while ((m = spellRe.exec(scan)) !== null) { us[m[1].toLowerCase()] = cfg.uk_spelling[m[1].toLowerCase()]; }
  const usList = Object.keys(us).map(function (k) { return k + ' → ' + us[k]; });
  if (usList.length) {
    add('SPELL_US', 'medium', 'content', 'US spelling found. Messages for UK patients should use UK English.', usList.join('; '), 'Use the UK spelling shown.', true);
  }

  const dates = scan.match(usDateRe);
  if (dates) {
    add('DATE_US', 'medium', 'content', 'Date looks like US month/day order. UK messages use day/month/year.', Array.from(new Set(dates)).join(', '), 'Write dates as day/month/year, or spell the month (21 October 2026).');
  }
  const dollars = scan.match(dollarRe);
  if (dollars) {
    add('CURRENCY_USD', 'medium', 'content', 'Dollar amount found in a UK message.', Array.from(new Set(dollars)).join(', '), 'Confirm the amount and use £.');
  }

  const wordy = {};
  plainRe.lastIndex = 0;
  while ((m = plainRe.exec(scan)) !== null) { wordy[m[1].toLowerCase()] = cfg.plain_english[m[1].toLowerCase()]; }
  const wordyList = Object.keys(wordy).map(function (k) { return k + ' → ' + wordy[k]; });
  if (wordyList.length) {
    add('PLAIN_ENGLISH', 'low', 'content', 'Wordy or formal phrases found. Plain English is easier to read.', wordyList.join('; '), 'Use the simpler wording shown.', true);
  }
  out.push({ json: j });
}
return out;

// Placeholder checks: brackets, unknown names, wrong case, and required placeholders for the template type.
const cfg = $('2. Load Config').first().json.config;
const known = Object.keys(cfg.known_placeholders);
const norm = function (s) { return String(s).toLowerCase().replace(/[^a-z0-9]/g, ''); };
const knownNorm = {};
known.forEach(function (k) { knownNorm[norm(k)] = k; });

const lev = function (a, b) {
  const dp = [];
  for (let i = 0; i <= a.length; i++) { dp.push([i]); }
  for (let k = 1; k <= b.length; k++) { dp[0][k] = k; }
  for (let i = 1; i <= a.length; i++) {
    for (let k = 1; k <= b.length; k++) {
      dp[i][k] = Math.min(dp[i - 1][k] + 1, dp[i][k - 1] + 1, dp[i - 1][k - 1] + (a[i - 1] === b[k - 1] ? 0 : 1));
    }
  }
  return dp[a.length][b.length];
};
const closest = function (name) {
  const target = norm(name);
  let best = null, bestD = 99;
  known.forEach(function (k) {
    const d = lev(target, norm(k));
    if (d < bestD) { bestD = d; best = k; }
  });
  return bestD <= 2 ? best : null;
};

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const add = function (code, severity, category, message, evidence, fix, auto) {
    j.issues.push({ code: code, severity: severity, category: category, owner: cfg.owners[category],
      message: message, evidence: evidence || '', fix: fix || '', auto_fixable: !!auto });
  };
  const text = j.subject + '\n' + j.body;

  const opens = (text.match(/\{\{/g) || []).length;
  const closes = (text.match(/\}\}/g) || []).length;
  if (opens !== closes) {
    add('PH_UNBALANCED', 'high', 'config', 'A placeholder has mismatched brackets, so it will show as raw text to the patient.',
      opens + ' opening {{ and ' + closes + ' closing }}', 'Make sure every {{ has a matching }}.', true);
  }

  const single = text.match(/(?<!\{)\{\s*[A-Za-z_][A-Za-z0-9_ ]*\}(?!\})/g);
  if (single) {
    add('PH_SYNTAX', 'high', 'config', 'Placeholder uses single brackets. The platform needs double brackets.',
      Array.from(new Set(single)).join(', '), 'Change {name} to {{name}}.', true);
  }

  const found = [];
  const re = /\{\{\s*([^{}]+?)\s*\}\}/g;
  let m;
  while ((m = re.exec(text)) !== null) { found.push(m[1].trim()); }
  const distinct = Array.from(new Set(found));
  j.placeholders = distinct;

  const usedNorm = {};
  distinct.forEach(function (name) {
    usedNorm[norm(name)] = true;
    if (known.indexOf(name) !== -1) { return; }
    if (known.indexOf(name.toLowerCase()) !== -1) {
      add('PH_CASE', 'low', 'config', 'Placeholder name has the wrong capitalisation.', '{{' + name + '}}', 'Use {{' + name.toLowerCase() + '}}.', true);
      return;
    }
    if (knownNorm[norm(name)]) {
      add('PH_UNKNOWN', 'high', 'config', 'Placeholder name is not recognised. It looks like a typo.', '{{' + name + '}}', 'Use {{' + knownNorm[norm(name)] + '}}.', true);
      return;
    }
    const guess = closest(name);
    add('PH_UNKNOWN', 'high', 'config', 'Placeholder name is not recognised, so it would not be filled in.', '{{' + name + '}}',
      guess ? 'Did you mean {{' + guess + '}}?' : 'Use one of the approved placeholders, or ask Workflow Config to add this one.', false);
  });

  const rule = cfg.type_rules[j.type];
  if (rule && j.body.trim() !== '') {
    const missing = rule.required.filter(function (k) { return !usedNorm[norm(k)]; });
    if (missing.length) {
      add('PH_MISSING_REQUIRED', 'high', 'config', 'A placeholder this type of message needs is missing.',
        missing.map(function (k) { return '{{' + k + '}}'; }).join(', '), 'Add the missing placeholder(s) so the patient gets the full details.', false);
    }
  }
  out.push({ json: j });
}
return out;

// Compliance and safety checks: personal data, sensitive terms in SMS, risky health claims, marketing opt-out, pressure wording, script content.
const cfg = $('2. Load Config').first().json.config;
const sensitiveRe = new RegExp('(' + cfg.sensitive_terms.join('|') + ')', 'gi');
const claimRe = new RegExp('(' + cfg.risky_claims.join('|') + ')', 'gi');
const pressureRe = new RegExp('(' + cfg.pressure_phrases.map(function (p) { return p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }).join('|') + ')', 'gi');
const nhsRe = /\b\d{3}[\s-]?\d{3}[\s-]?\d{4}\b/g;
const mobileRe = /(?:\+44\s?7\d{3}|\b07\d{3})\s?\d{3}\s?\d{3}\b/g;
const emailRe = /[A-Za-z0-9._%+-]+@([A-Za-z0-9.-]+\.[A-Za-z]{2,})/g;
const scriptRe = /<\s*(script|iframe|object|embed)\b/i;

const uniq = function (arr) { return Array.from(new Set(arr)); };

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const add = function (code, severity, category, message, evidence, fix) {
    j.issues.push({ code: code, severity: severity, category: category, owner: cfg.owners[category],
      message: message, evidence: evidence || '', fix: fix || '', auto_fixable: false });
  };
  const raw = j.subject + '\n' + j.body;
  const scan = raw.replace(/\{\{[^}]*\}\}/g, ' ').replace(/https?:\/\/\S+/g, ' ');

  const nhs = scan.match(nhsRe);
  if (nhs) {
    add('PII_NHS', 'critical', 'compliance', 'Text contains what looks like an NHS number. Patient identifiers must never be typed into a template.',
      uniq(nhs).join(', '), 'Remove it. Use a {{reference_number}} placeholder if a reference is needed.');
  }
  const mobiles = scan.match(mobileRe);
  if (mobiles) {
    add('PII_PHONE', 'high', 'compliance', 'A mobile number is typed into the text. It may be personal, and it will not update if the number changes.',
      uniq(mobiles).join(', '), 'Use {{clinic_phone}} instead.');
  }
  const emails = [];
  const free = [];
  let m;
  emailRe.lastIndex = 0;
  while ((m = emailRe.exec(scan)) !== null) {
    const domain = m[1].toLowerCase();
    if (cfg.allowed_email_domains.indexOf(domain) === -1) {
      emails.push(m[0]);
      if (cfg.free_mail_domains.indexOf(domain) !== -1) { free.push(m[0]); }
    }
  }
  if (free.length) {
    add('PII_EMAIL', 'high', 'compliance', 'A personal-style email address (free webmail) is typed into the text.', uniq(free).join(', '), 'Use an official organisation address.');
  } else if (emails.length) {
    add('PII_EMAIL', 'medium', 'compliance', 'An email address is typed into the text.', uniq(emails).join(', '), 'Check it is an approved organisation address.');
  }

  // Sensitive health terms: never in an SMS body, never in an email subject line (shown in lock-screen previews)
  const sensitiveText = j.channel === 'sms' ? scan : (j.channel === 'email' ? j.subject : '');
  if (sensitiveText) {
    const hits = sensitiveText.match(sensitiveRe);
    if (hits) {
      add('SENSITIVE_PREVIEW', 'critical', 'clinical', 'Sensitive health information appears where it can be read on a lock screen or by someone else.',
        uniq(hits.map(function (h) { return h.toLowerCase(); })).join(', '), 'Remove the condition or result. Ask the patient to contact the clinic or log in instead.');
    }
  }

  const claims = scan.match(claimRe);
  if (claims) {
    add('CLAIM_RISKY', 'high', 'compliance', 'Absolute or unproven health claim found.',
      uniq(claims.map(function (c) { return c.toLowerCase(); })).join(', '), 'Remove the claim, or have it approved by Clinical Safety.');
  }

  if (j.type === 'marketing') {
    let hasOptOut = false;
    if (j.channel === 'sms') { hasOptOut = /\bstop\b/i.test(scan); }
    else if (j.channel === 'email') { hasOptOut = /\{\{\s*unsubscribe_link\s*\}\}/i.test(raw) || /unsubscribe/i.test(scan); }
    else { hasOptOut = /\bstop\b/i.test(scan) || /unsubscribe/i.test(raw); }
    if (!hasOptOut && j.body.trim() !== '') {
      add('MKT_NO_OPTOUT', 'critical', 'compliance', 'Marketing message has no way to opt out.', '',
        j.channel === 'sms' ? 'Add "Reply STOP to opt out."' : 'Add an unsubscribe link: {{unsubscribe_link}}.');
    }
  }

  const pressure = scan.match(pressureRe);
  if (pressure) {
    add('PRESSURE', 'medium', 'content', 'Pressure wording found. It is not appropriate in health communications.',
      uniq(pressure.map(function (p) { return p.toLowerCase(); })).join(', '), 'Use calm, factual wording.');
  }

  if (scriptRe.test(raw)) {
    add('HTML_SCRIPT', 'high', 'compliance', 'Script or embedded-object tags found in the text.', raw.match(scriptRe)[0], 'Remove all script tags. Messages must be plain text or approved HTML only.');
  }
  out.push({ json: j });
}
return out;

// Delivery and style checks: SMS length and characters, email subject and sign-off, capitals, exclamation marks, spacing, readability.
const cfg = $('2. Load Config').first().json.config;
const GSM = "@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !\"#¤%&'()*+,-./0123456789:;<=>?¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà^{}\\[~]|€";

const render = function (text) {
  return text.replace(/\{\{\s*([^{}]+?)\s*\}\}/g, function (all, name) {
    const v = cfg.known_placeholders[name.trim()];
    return v !== undefined ? v : 'XXXXXXXX';
  });
};

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const add = function (code, severity, category, message, evidence, fix, auto) {
    j.issues.push({ code: code, severity: severity, category: category, owner: cfg.owners[category],
      message: message, evidence: evidence || '', fix: fix || '', auto_fixable: !!auto });
  };
  const bodyEmpty = j.body.trim() === '';

  if (j.channel === 'sms' && !bodyEmpty) {
    const sample = render(j.body);
    const odd = [];
    for (const ch of sample) { if (GSM.indexOf(ch) === -1) { odd.push(ch); } }
    const unicode = odd.length > 0;
    const len = sample.length; // UTF-16 units, which is how SMS counts Unicode text
    const s = cfg.sms;
    const segments = unicode ? (len <= s.unicode_single ? 1 : Math.ceil(len / s.unicode_multi))
                             : (len <= s.single ? 1 : Math.ceil(len / s.multi));
    j.sms_chars = len;
    j.sms_segments = segments;
    j.sms_unicode = unicode;
    if (unicode) {
      // Only smart quotes and dashes can be swapped safely. Emoji and other symbols need a person to decide.
      const swappable = ['‘', '’', '“', '”', '–', '—'];
      const canAuto = odd.every(function (ch) { return swappable.indexOf(ch) !== -1; });
      add('SMS_UNICODE', 'medium', 'content', 'Characters outside the standard SMS set (smart quotes, dashes, emoji). The message is sent as Unicode, so each part holds only 70 characters instead of 160.',
        Array.from(new Set(odd)).slice(0, 6).join(' '),
        canAuto ? 'Use plain apostrophes and quotes (suggested below).' : 'Use plain apostrophes and quotes (suggested below) and remove emoji or symbols by hand.', canAuto);
    }
    if (segments > s.max_segments) {
      add('SMS_LONG', 'medium', 'content', 'Message will be sent as ' + segments + ' SMS parts (' + len + ' characters once filled in). Longer messages cost more and may arrive out of order.',
        len + ' characters, limit ' + s.max_segments + ' parts', 'Shorten the message, or move detail to a link.');
    }
  }

  if (j.channel === 'email' && !bodyEmpty) {
    if (j.subject.trim() === '') {
      add('EMAIL_NO_SUBJECT', 'high', 'content', 'Email has no subject line.', '', 'Add a short, clear subject line.');
    } else if (j.subject.length > cfg.email.subject_max) {
      add('EMAIL_SUBJECT_LONG', 'low', 'content', 'Subject line is long and may be cut off on phones.',
        j.subject.length + ' characters, limit ' + cfg.email.subject_max, 'Shorten to ' + cfg.email.subject_max + ' characters or fewer.');
    }
    if (!/(kind regards|best wishes|yours sincerely|yours faithfully|many thanks|thank you|regards)/i.test(j.body)) {
      add('EMAIL_NO_SIGNOFF', 'low', 'content', 'Email has no sign-off.', '', 'End with a sign-off such as "Kind regards".');
    }
  }

  if (!bodyEmpty) {
    const scan = (j.subject + '\n' + j.body).replace(/\{\{[^}]*\}\}/g, ' ').replace(/https?:\/\/\S+/g, ' ');
    const caps = (scan.match(/\b[A-Z]{4,}\b/g) || []).filter(function (w) { return cfg.allowed_caps_words.indexOf(w) === -1; });
    if (caps.length >= 2) {
      add('CAPS', 'medium', 'content', 'Several words are in ALL CAPITALS, which reads as shouting.', Array.from(new Set(caps)).slice(0, 8).join(', '), 'Use sentence case.');
    }
    const bangs = (scan.match(/!/g) || []).length;
    if (bangs > cfg.thresholds.max_exclamations) {
      add('EXCLAIM', 'low', 'content', 'Too many exclamation marks for a health message.', bangs + ' found', 'Keep the tone calm. One at most.');
    }
    if (/\S {2,}\S/.test(j.body) || /[ \t]+(\n|$)/.test(j.body) || /^\s|\s$/.test(j.body)) {
      add('SPACING', 'low', 'content', 'Extra spaces at the start, end or between words.', '', 'Remove the extra spaces.', true);
    }
    const rendered = render(scan);
    const sentences = rendered.split(/(?<=[.!?])\s+|\n+/).map(function (x) { return x.trim(); }).filter(function (x) { return x.length > 0; });
    let longest = 0;
    sentences.forEach(function (s) { const w = s.split(/\s+/).length; if (w > longest) { longest = w; } });
    j.longest_sentence_words = longest;
    if (longest > cfg.thresholds.max_sentence_words) {
      add('READABILITY', 'medium', 'content', 'A sentence is too long to read easily.', 'Longest sentence: ' + longest + ' words (limit ' + cfg.thresholds.max_sentence_words + ')', 'Split it into shorter sentences.');
    }
  }
  out.push({ json: j });
}
return out;

// Suggest safe, mechanical fixes only (UK spelling, plain English, spacing, SMS punctuation, bracket typos).
// Nothing is changed in the original. A person must approve every change. Compliance and clinical issues are never auto-fixed.
const cfg = $('2. Load Config').first().json.config;
const escRe = function (s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); };
const known = Object.keys(cfg.known_placeholders);
const norm = function (s) { return String(s).toLowerCase().replace(/[^a-z0-9]/g, ''); };
const knownNorm = {};
known.forEach(function (k) { knownNorm[norm(k)] = k; });

const spellRe = new RegExp('\\b(' + Object.keys(cfg.uk_spelling).sort(function (a, b) { return b.length - a.length; }).map(escRe).join('|') + ')\\b', 'gi');
const plainRe = new RegExp('\\b(' + Object.keys(cfg.plain_english).sort(function (a, b) { return b.length - a.length; }).map(escRe).join('|') + ')\\b', 'gi');

const matchCase = function (src, rep) {
  if (src.length > 1 && src === src.toUpperCase()) { return rep.toUpperCase(); }
  if (src.charAt(0) === src.charAt(0).toUpperCase() && src.charAt(0) !== src.charAt(0).toLowerCase()) { return rep.charAt(0).toUpperCase() + rep.slice(1); }
  return rep;
};

const fixText = function (text, channel, log) {
  const store = [];
  let t = text.replace(/\{\{[^}]*\}\}|https?:\/\/\S+/g, function (m) { store.push(m); return '@@PH' + (store.length - 1) + '@@'; });

  t = t.replace(spellRe, function (m) { const r = matchCase(m, cfg.uk_spelling[m.toLowerCase()]); log.push(m + ' → ' + r); return r; });
  t = t.replace(plainRe, function (m) { const r = matchCase(m, cfg.plain_english[m.toLowerCase()]); log.push(m + ' → ' + r); return r; });

  const before = t;
  t = t.replace(/[ \t]{2,}/g, ' ').replace(/[ \t]+\n/g, '\n').trim();
  if (t !== before) { log.push('extra spaces removed'); }

  if (channel === 'sms') {
    const b2 = t;
    t = t.replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/[–—]/g, '-');
    if (t !== b2) { log.push('smart punctuation replaced with plain characters'); }
  }

  t = t.replace(/@@PH(\d+)@@/g, function (m, i) { return store[Number(i)]; });

  // bracket typos, placeholder names and case
  t = t.replace(/(?<!\{)\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}(?!\})/g, function (m, name) {
    const k = knownNorm[norm(name)];
    if (k) { log.push(m + ' → {{' + k + '}}'); return '{{' + k + '}}'; }
    return m;
  });
  t = t.replace(/\{\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}(?!\})/g, function (m, name) {
    const k = knownNorm[norm(name)];
    if (k) { log.push('closing bracket added: {{' + k + '}}'); return '{{' + k + '}}'; }
    return m;
  });
  t = t.replace(/\{\{\s*([^{}]+?)\s*\}\}/g, function (m, name) {
    const trimmed = name.trim();
    const k = knownNorm[norm(trimmed)];
    if (k && k !== trimmed) { log.push('{{' + trimmed + '}} → {{' + k + '}}'); return '{{' + k + '}}'; }
    return m;
  });
  return t;
};

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const log = [];
  j.suggested_subject = fixText(j.subject, j.channel, log);
  j.suggested_body = fixText(j.body, j.channel, log);
  j.auto_fixes = Array.from(new Set(log));
  j.auto_fix_count = j.auto_fixes.length;
  j.suggestion_changes_text = (j.suggested_subject !== j.subject) || (j.suggested_body !== j.body);
  out.push({ json: j });
}
return out;

// Score each template and decide what happens next.
// BLOCKED = any critical issue. NEEDS REVIEW = any high issue or a low score. APPROVED WITH NOTES = only minor issues. APPROVED = nothing found.
const cfg = $('2. Load Config').first().json.config;
const w = cfg.severity_weights;
const rank = { critical: 0, high: 1, medium: 2, low: 3 };

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const counts = { critical: 0, high: 0, medium: 0, low: 0 };
  let penalty = 0;
  j.issues.forEach(function (i) { counts[i.severity] += 1; penalty += w[i.severity]; });
  j.issues.sort(function (a, b) { return rank[a.severity] - rank[b.severity]; });

  j.issue_counts = counts;
  j.issue_total = j.issues.length;
  j.quality_score = Math.max(0, 100 - penalty);

  if (counts.critical > 0) { j.status = 'BLOCKED'; }
  else if (counts.high > 0 || j.quality_score < cfg.thresholds.review_below_score) { j.status = 'NEEDS REVIEW'; }
  else if (j.issues.length > 0) { j.status = 'APPROVED WITH NOTES'; }
  else { j.status = 'APPROVED'; }

  const teams = [];
  j.issues.forEach(function (i) { if (teams.indexOf(i.owner) === -1) { teams.push(i.owner); } });
  j.route_to = teams;

  const manual = j.issues.filter(function (i) { return !i.auto_fixable; }).length;
  j.manual_issue_count = manual;
  if (j.status === 'BLOCKED') { j.next_action = 'Do not send. Fix the critical issue(s) and run the check again. Route to: ' + teams.join(', ') + '.'; }
  else if (j.status === 'NEEDS REVIEW') { j.next_action = 'Hold until reviewed by: ' + teams.join(', ') + '.'; }
  else if (j.status === 'APPROVED WITH NOTES') { j.next_action = 'Safe to use. Apply the suggested wording fixes when convenient.'; }
  else { j.next_action = 'No action needed.'; }
  out.push({ json: j });
}
return out;

// Roll the individual results up into one run summary and a flat issue list (easy to paste into a spreadsheet).
const cfg = $('2. Load Config').first().json.config;
const results = ($input.first().json.results || []);

const statuses = ['APPROVED', 'APPROVED WITH NOTES', 'NEEDS REVIEW', 'BLOCKED'];
const status_counts = {};
statuses.forEach(function (s) { status_counts[s] = 0; });
const severity_totals = { critical: 0, high: 0, medium: 0, low: 0 };
const codeMap = {};
const teamMap = {};
const issues_flat = [];
let scoreSum = 0;
let autoFixable = 0;
let issueTotal = 0;

results.forEach(function (r) {
  status_counts[r.status] = (status_counts[r.status] || 0) + 1;
  scoreSum += r.quality_score;
  r.issues.forEach(function (i) {
    issueTotal += 1;
    severity_totals[i.severity] += 1;
    if (i.auto_fixable) { autoFixable += 1; }
    if (!codeMap[i.code]) { codeMap[i.code] = { code: i.code, severity: i.severity, count: 0, templates: [] }; }
    codeMap[i.code].count += 1;
    codeMap[i.code].templates.push(r.template_id);
    if (!teamMap[i.owner]) { teamMap[i.owner] = {}; }
    teamMap[i.owner][r.template_id] = true;
    issues_flat.push({ template_id: r.template_id, template_name: r.name, status: r.status, severity: i.severity, code: i.code,
      owner: i.owner, message: i.message, evidence: i.evidence, fix: i.fix, auto_fixable: i.auto_fixable });
  });
});

const top_codes = Object.keys(codeMap).map(function (k) { return codeMap[k]; }).sort(function (a, b) { return b.count - a.count; });
const team_queue = Object.keys(teamMap).map(function (t) {
  return { team: t, templates: Object.keys(teamMap[t]) };
}).sort(function (a, b) { return b.templates.length - a.templates.length; });

const total = results.length;
const summary = {
  report_date: cfg.report_date,
  total_templates: total,
  status_counts: status_counts,
  block_count: status_counts['BLOCKED'],
  review_count: status_counts['NEEDS REVIEW'],
  clean_count: status_counts['APPROVED'] + status_counts['APPROVED WITH NOTES'],
  average_score: total ? Math.round(scoreSum / total) : 0,
  issue_total: issueTotal,
  severity_totals: severity_totals,
  auto_fixable_issues: autoFixable,
  top_codes: top_codes,
  team_queue: team_queue,
  manual_minutes_assumed: total * cfg.minutes_manual_review_per_template,
  minutes_per_template_assumption: cfg.minutes_manual_review_per_template
};
return [{ json: { summary: summary, results: results, issues_flat: issues_flat } }];

// At least one template is BLOCKED: write a draft alert. It is NOT sent anywhere. A person copies it into Slack or email.
const d = $input.first().json;
const blocked = d.results.filter(function (r) { return r.status === 'BLOCKED'; });
const lines = blocked.map(function (r) {
  const crit = r.issues.filter(function (i) { return i.severity === 'critical'; })[0];
  return '• ' + r.template_id + ' – ' + r.name + ' [' + r.channel + ']: ' + (crit ? crit.message : 'Critical issue') + ' (route to ' + (crit ? crit.owner : 'owner') + ')';
});
const teams = [];
blocked.forEach(function (r) { r.issues.filter(function (i) { return i.severity === 'critical'; }).forEach(function (i) { if (teams.indexOf(i.owner) === -1) { teams.push(i.owner); } }); });

const text = ':rotating_light: Template QA: ' + blocked.length + ' template(s) BLOCKED out of ' + d.summary.total_templates + ' checked.\n' +
  lines.join('\n') + '\n\nDo not send these until fixed. Teams to action: ' + teams.join(', ') + '.';
d.alert = {
  level: 'escalation',
  draft_only: true,
  suggested_channel: '#template-qa',
  subject: 'Template QA: ' + blocked.length + ' blocked template(s)',
  text: text,
  blocked_ids: blocked.map(function (r) { return r.template_id; }),
  teams: teams
};
return [{ json: d }];

// No template is BLOCKED: write a short all-clear note (draft only, not sent).
const d = $input.first().json;
d.alert = {
  level: 'all_clear',
  draft_only: true,
  suggested_channel: '#template-qa',
  subject: 'Template QA: no blocked templates',
  text: 'Template QA: ' + d.summary.total_templates + ' template(s) checked. None blocked. ' + d.summary.review_count + ' need review.',
  blocked_ids: [],
  teams: []
};
return [{ json: d }];

// Build a self-contained HTML report (no external files). All text is escaped before it is placed in the page.
const cfg = $('2. Load Config').first().json.config;
const d = $input.first().json;
const s = d.summary;

const esc = function (v) {
  return String(v === null || v === undefined ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
};
const pill = function (status) {
  const cls = { 'APPROVED': 'ok', 'APPROVED WITH NOTES': 'note', 'NEEDS REVIEW': 'warn', 'BLOCKED': 'bad' }[status] || 'note';
  return '<span class="pill ' + cls + '">' + esc(status) + '</span>';
};
const sevDot = function (sev) { return '<span class="sev ' + esc(sev) + '">' + esc(sev) + '</span>'; };

const tiles = [
  ['Templates checked', s.total_templates, ''],
  ['Approved (incl. notes)', s.clean_count, 'ok'],
  ['Need review', s.review_count, 'warn'],
  ['Blocked', s.block_count, 'bad'],
  ['Average quality score', s.average_score + '/100', ''],
  ['Issues found', s.issue_total + ' (' + s.auto_fixable_issues + ' auto-fixable)', '']
].map(function (t) { return '<div class="tile ' + t[2] + '"><div class="n">' + esc(t[1]) + '</div><div class="l">' + esc(t[0]) + '</div></div>'; }).join('');

const maxCode = s.top_codes.length ? s.top_codes[0].count : 1;
const codeRows = s.top_codes.slice(0, 12).map(function (c) {
  return '<div class="bar"><div class="bl">' + esc(c.code) + ' ' + sevDot(c.severity) + '</div><div class="bt"><div class="bf ' + esc(c.severity) + '" style="width:' + Math.round(100 * c.count / maxCode) + '%"></div></div><div class="bn">' + c.count + '</div></div>';
}).join('');

const teamRows = s.team_queue.map(function (t) {
  return '<tr><td><b>' + esc(t.team) + '</b></td><td>' + t.templates.length + '</td><td>' + esc(t.templates.join(', ')) + '</td></tr>';
}).join('');

const rows = d.results.map(function (r) {
  const issues = r.issues.map(function (i) {
    return '<li>' + sevDot(i.severity) + ' <b>' + esc(i.code) + '</b>: ' + esc(i.message) +
      (i.evidence ? ' <span class="ev">Found: ' + esc(i.evidence) + '</span>' : '') +
      (i.fix ? ' <span class="fx">Fix: ' + esc(i.fix) + '</span>' : '') +
      (i.auto_fixable ? ' <span class="af">auto-fix suggested</span>' : '') + '</li>';
  }).join('');
  const sms = r.channel === 'sms' && r.sms_segments ? ' &middot; ' + r.sms_segments + ' SMS part(s), ' + r.sms_chars + ' chars' : '';
  const sug = r.suggestion_changes_text
    ? '<div class="sug"><b>Suggested wording (needs human approval)</b>' +
      (r.suggested_subject ? '<div><i>Subject:</i> ' + esc(r.suggested_subject) + '</div>' : '') +
      '<pre>' + esc(r.suggested_body) + '</pre><div class="ev">Changes: ' + esc(r.auto_fixes.join('; ')) + '</div></div>'
    : '';
  const detail = '<details><summary>' + r.issue_total + ' issue(s)</summary><div class="d">' +
    (issues ? '<ul>' + issues + '</ul>' : '<p>No issues found.</p>') +
    '<div class="ev">Next action: ' + esc(r.next_action) + '</div>' + sug +
    '<div class="orig"><b>Original text</b>' + (r.subject ? '<div><i>Subject:</i> ' + esc(r.subject) + '</div>' : '') + '<pre>' + esc(r.body) + '</pre></div></div></details>';
  return '<tr><td>' + esc(r.template_id) + '</td><td>' + esc(r.name) + '<div class="sub">' + esc(r.type || 'no type') + ' &middot; ' + esc(r.channel || 'no channel') + sms + '</div></td><td>' + pill(r.status) +
    '</td><td class="num">' + r.quality_score + '</td><td>' + esc(r.route_to.join(', ') || '-') + '</td><td>' + detail + '</td></tr>';
}).join('');

const alertBox = d.alert
  ? '<div class="alert ' + esc(d.alert.level) + '"><b>Draft ' + (d.alert.level === 'escalation' ? 'escalation' : 'all-clear') + ' message (not sent)</b><pre>' + esc(d.alert.text) + '</pre></div>'
  : '';

const css = ':root{--bg:#f6f7f9;--card:#fff;--ink:#1c2430;--mut:#5d6b7b;--line:#dde2e8;--ok:#1f7a45;--note:#2a6fb0;--warn:#b86e00;--bad:#b3261e}' +
