  '.alert{border:1px solid var(--line);border-left:5px solid var(--ok);background:var(--card);border-radius:8px;padding:12px;margin:16px 0}.alert.escalation{border-left-color:var(--bad)}' +
  '.banner{background:var(--card);border:1px dashed var(--line);border-radius:8px;padding:8px 12px;color:var(--mut);font-size:12px;margin-top:10px}';

const html = '<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(cfg.title) + '</title><style>' + css + '</style></head><body><div class="w">' +
  '<h1>' + esc(cfg.title) + '</h1><div class="m">Run date ' + esc(s.report_date) + ' &middot; workflow v' + esc(cfg.workflow_version) + '</div>' +
  '<div class="banner">Demo run on synthetic (fictional) templates. Nothing was sent to anyone. Suggested wording is a proposal: a person approves every change.</div>' +
  '<div class="tiles">' + tiles + '</div>' + alertBox +
  '<h2>Most common issues</h2><div class="card">' + (codeRows || '<span class="m">No issues found.</span>') + '</div>' +
  '<h2>Work queue by team</h2><div class="card"><table><thead><tr><th>Team</th><th>Templates</th><th>IDs</th></tr></thead><tbody>' + (teamRows || '<tr><td colspan="3" class="m">Nothing to action.</td></tr>') + '</tbody></table></div>' +
  '<h2>All templates</h2><div class="card"><table><thead><tr><th>ID</th><th>Template</th><th>Status</th><th class="num">Score</th><th>Route to</th><th>Details</th></tr></thead><tbody>' + rows + '</tbody></table></div>' +
  '<p class="m">Estimated reviewer time for this batch if checked by hand: about ' + s.manual_minutes_assumed + ' minutes (assumes ' + s.minutes_per_template_assumption + ' minutes per template; edit in 2. Load Config).</p>' +
  '</div></body></html>';

d.html_report = html;
return [{ json: d }];
